    dynamic: { resetTableCaption: '\u5df2\u9a8c\u8bc1\u5730\u56fe\u8bb0\u5f55\u7684\u5f53\u524d\u6784\u5efa\u65f6\u95f4\u6362\u7b97', resetTableHeaders: ['\u53c2\u8003\u65f6\u533a', '\u91cd\u7f6e\u65f6\u95f4', '\u9605\u8bfb\u8bf4\u660e'], resetPending: '\u5f85\u9a8c\u8bc1', resetZones: [['UTC', 'UTC', '\u7a33\u5b9a\u7684\u6765\u6e90\u65f6\u95f4\u53c2\u8003'], ['\u4e2d\u56fd\u6807\u51c6\u65f6\u95f4 (UTC+8)', 'Asia/Shanghai', '\u5f53\u524d\u8bb0\u5f55\u5728\u4e2d\u56fd\u65f6\u95f4\u662f\u6b21\u65e5'], ['\u65e5\u672c / \u97e9\u56fd (UTC+9)', 'Asia/Tokyo', '\u65e5\u672c\u548c\u97e9\u56fd\u4f7f\u7528\u76f8\u540c\u504f\u79fb'], ['\u4e2d\u6b27\u590f\u4ee4\u65f6 (UTC+2)', 'Europe/Berlin', '\u51ac\u5b63\u672c\u5730\u65f6\u95f4\u63d0\u524d\u4e00\u5c0f\u65f6'], ['\u82f1\u56fd\u590f\u4ee4\u65f6 (UTC+1)', 'Europe/London', '\u51ac\u5b63\u672c\u5730\u65f6\u95f4\u63d0\u524d\u4e00\u5c0f\u65f6'], ['\u7f8e\u56fd\u4e1c\u90e8\u590f\u4ee4\u65f6 (UTC-4)', 'America/New_York', '\u6807\u51c6\u65f6\u95f4\u63d0\u524d\u4e00\u5c0f\u65f6'], ['\u7f8e\u56fd\u897f\u90e8\u590f\u4ee4\u65f6 (UTC-7)', 'America/Los_Angeles', '\u6807\u51c6\u65f6\u95f4\u63d0\u524d\u4e00\u5c0f\u65f6']], nextDay: '\u6b21\u65e5', previousDay: '\u524d\u4e00\u5929', historyEmpty: '\u672c\u6b21\u6784\u5efa\u6ca1\u6709\u53ef\u9a8c\u8bc1\u7684\u8f6e\u6362\u8bb0\u5f55\u3002', historyCaption: '\u6700\u8fd1\u5df2\u9a8c\u8bc1\u7684 PEAK \u8f6e\u6362\u8bb0\u5f55', historyHeaders: ['\u65e5\u671f', '\u5730\u56fe\u6216\u5e8f\u5217', '\u751f\u7269\u7fa4\u7cfb\u73af\u5883', '\u6765\u6e90'], historyPending: '\u5f85\u786e\u8ba4', historySourcePending: '\u6765\u6e90\u5f85\u786e\u8ba4', historySourceVerified: '\u5df2\u9a8c\u8bc1\u7684\u6765\u6e90', historyNote: '\u53ea\u6709\u6784\u5efa\u6765\u6e90\u65e5\u671f\u5339\u914d\u4e14\u6709\u8db3\u591f\u4f4d\u7f6e\u5b57\u6bb5\u65f6\u624d\u4f1a\u6dfb\u52a0\u884c\u3002\u8fd9\u4e9b\u662f\u89c2\u5bdf\u8bb0\u5f55\uff0c\u4e0d\u662f\u5bf9\u672a\u6765\u5468\u671f\u7684\u4fdd\u8bc1\u3002' },
